 void offset(LinearLayout parent,String title,String key){subtitle(parent,title);SeekBar bar=new SeekBar(this);bar.setMax(80);bar.setProgress(prefs().getInt(key,0)+40);parent.addView(bar);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}public void onProgressChanged(SeekBar b,int value,boolean user){if(user){prefs().edit().putInt(key,value-40).apply();refreshHalo();}}});}
 void refreshHalo(){VoiceService s=VoiceService.live;if(s!=null&&s.island!=null)s.island.show(s.state,s.message);if(preview!=null)preview.show(preview.state,preview.message);}
 boolean phoneGranted(){if(PhoneAccessibility.live!=null)return true;try{for(AccessibilityServiceInfo a:getSystemService(AccessibilityManager.class).getEnabledAccessibilityServiceList(AccessibilityServiceInfo.FEEDBACK_ALL_MASK)){android.content.pm.ServiceInfo s=a.getResolveInfo().serviceInfo;if(s.packageName.equals(getPackageName())&&s.name.equals(PhoneAccessibility.class.getName()))return true;}}catch(Exception ignored){}return false;}
 void refreshPermissions(){
  permissionGranted[0]=checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;permissionGranted[1]=Settings.canDrawOverlays(this);NotificationManager nm=getSystemService(NotificationManager.class);NotificationChannel channel=nm.getNotificationChannel("eva-voice");permissionGranted[2]=nm.areNotificationsEnabled()&&(channel==null||channel.getImportance()!=NotificationManager.IMPORTANCE_NONE);permissionGranted[3]=phoneGranted();
  int count=0;for(int i=0;i<4;i++){boolean ok=permissionGranted[i];if(ok)count++;permissionBadges[i].setText(ok?"✓":"？");permissionBadges[i].setTextColor(ok?GREEN:0xffaa7200);permissionBadges[i].setBackground(bg(ok?0xffe2f7ee:0xfffff3d8,17));String detail=ok?"已开启":"未开启 · 点击设置";if(i==3&&ok)detail=PhoneAccessibility.live==null?"已授权 · 等待系统连接":PhoneAccessibility.armed?"已授权 · 控制已开启":"已授权 · 控制未开启";permissionDetails[i].setText(detail);}
  permissionSummary.setText("权限状态 · "+count+"/4 已开启");
 }
 void refreshState(){if(wakeSwitch==null)return;updating=true;VoiceService s=VoiceService.live;if(s!=null||SystemClock.elapsedRealtime()-startAt>5000)starting=false;boolean on=s!=null&&!s.destroyed;
  wakeSwitch.setChecked(on||starting);wakeSwitch.setContentDescription("语音唤醒，"+(on?"已开启":starting?"正在开启":"已关闭"));status.setText(on?(s.ready?"● 已开启":"正在开启…"):starting?"正在开启…":"○ 已关闭");status.setTextColor(on?GREEN:INK);
  String error=prefs().getString("lastError","");statusDetail.setText(on?(s.state.equals("listening")?s.listeningHint:VoiceIsland.label(s.state)+" · "+(s.state.equals("idle")?"说“你好艾瓦”唤醒":s.message)):starting?"正在准备麦克风与本地语音":"麦克风未开启，不会监听。"+(error.isEmpty()?"":"\n"+error));
  boolean listening=on&&s.state.equals("listening");listenSwitch.setChecked(listening);listenSwitch.setEnabled(!VoiceAgent.busy&&!starting);listenDetail.setText(listening?(s.sendCountdown>0?"正在等你说完 · 继续说会接着听":"已开启 · 正在接收你的指令"):"已关闭 · 打开后直接说话，不用唤醒词");
  liveText.setVisibility(on&&!s.transcript.isEmpty()?View.VISIBLE:View.GONE);if(on)liveText.setText("听写内容："+s.transcript);
  boolean review=on&&s.state.equals("review");reviewBox.setVisibility(review?View.VISIBLE:View.GONE);if(review){String key=s.utteranceId+":"+s.pendingText;if(!key.equals(reviewKey)){reviewKey=key;reviewInput.setText(s.pendingText);}}else reviewKey="";
  previewSwitch.setChecked(preview!=null);previewSwitch.setEnabled(!on&&!starting);previewDetail.setText(preview!=null?"已开启 · 仅预览，不录音":on?"关闭语音后可单独预览":"已关闭 · 打开后看光圈与提示效果");
  for(String key:preferences.keySet()){boolean enabled=prefs().getBoolean(key,true);preferences.get(key).setChecked(enabled);preferenceDetails.get(key).setText(key.equals("wakeSound")?(enabled?"已开启 · 跟随媒体音量":"已关闭 · 唤醒不播放声音"):key.equals("wakeVibration")?(enabled?"已开启 · 双段振动":"已关闭 · 唤醒不振动"):(enabled?"已开启 · 判断可执行且停顿后才提交":"已关闭 · 每次先检查，再确认发送"));}
  int selected=VoiceCommandPolicy.silenceMillis(prefs().getInt("silenceMs",3000));int[] seconds={2,3,5};for(int i=0;i<3;i++){boolean active=selected==seconds[i]*1000;pauseButtons[i].setText((active?"✓ ":"")+seconds[i]+" 秒");pauseButtons[i].setTextColor(active?Color.WHITE:INK);pauseButtons[i].setBackground(bg(active?GREEN:0xffedf3f4,12));}
  refreshPermissions();updating=false;
 }
 void managePermission(int index){if(index==0){if(!permissionGranted[0])requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},29);else startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}else if(index==1)startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));else if(index==2){if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=0)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},30);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));}else startActivity(new Intent(this,PhoneControlActivity.class));}
 void start(boolean direct){
  closePreview();refreshPermissions();if(!permissionGranted[0]||!permissionGranted[1]){int missing=!permissionGranted[0]?0:1;new AlertDialog.Builder(this).setTitle("还差一项权限").setMessage(missing==0?"请先开启麦克风权限，语音开关暂时保持关闭。":"请先允许显示在其他应用上层，语音开关暂时保持关闭。").setPositiveButton("去开启",(d,w)->managePermission(missing)).setNegativeButton("稍后",null).show();refreshState();return;}
  try{VoiceAgent.config(this);prefs().edit().remove("lastError").apply();starting=VoiceService.live==null;startAt=SystemClock.elapsedRealtime();startForegroundService(new Intent(this,VoiceService.class).setAction(direct?"listen":"start"));}catch(Exception e){starting=false;prefs().edit().putString("lastError",e.getMessage()).apply();new AlertDialog.Builder(this).setMessage(e.getMessage()).setPositiveButton("知道了",null).show();}refreshState();
 }
 void stopVoice(){starting=false;VoiceAgent.cancel(this);stopService(new Intent(this,VoiceService.class));closePreview();ui.post(this::refreshState);}
 void preview(){if(VoiceService.live!=null)return;if(!Settings.canDrawOverlays(this)){Toast.makeText(this,"请先开启“显示在其他应用上层”权限",1).show();return;}closePreview();preview=new VoiceIsland(this,this::closePreview,this::closePreview,()->{});preview.show("listening","");preview.level(.65f);VoiceService.playWakeFeedback(this);final VoiceIsland showing=preview;ui.postDelayed(()->{if(preview==showing){closePreview();refreshState();}},15000);}
 void closePreview(){if(preview!=null){preview.close();preview=null;}}
 protected void onResume(){super.onResume();ui.removeCallbacks(refresh);ui.post(refresh);}
 protected void onPause(){ui.removeCallbacks(refresh);super.onPause();}
